function kgPerCrop(harvests) {
  const totals = {};
  for (const h of harvests) totals[h.crop] = (totals[h.crop] || 0) + h.kg;
  return totals;
}

function aboveAverage(people) {
  if (!people.length) return [];
  const avg = people.reduce((s, p) => s + p.score, 0) / people.length;
  return people.filter((p) => p.score > avg).map((p) => p.name);
}
